    final int idx = i;
    watki[i] = new Thread(() -> { long s = 0; for (long j = idx*12_500_000L+1; j <= (idx+1)*12_500_000L; j++) s += j; wyniki[idx] = s; });
    watki[i].start();
}
for (Thread t : watki) t.join();
long suma = 0; for (long w : wyniki) suma += w;

