String recommendThreading(String taskType, int cores) {
    return switch (taskType) {
        case "IO" -> "watki pomagaja nawet na 1 rdzeniu (masz " + cores + ")";
        case "CPU" -> "watki pomagaja tylko przy wielu rdzeniach (masz " + cores + ")";
        default -> "nieznany typ zadania";
    };
}

