String buildTimingReport(int taskCount, int taskDurationMs) {
    long seq = mierzSekwencyjnie(taskCount, taskDurationMs);
    long conc = mierzWspolbieznie(taskCount, taskDurationMs);
    return String.format("zadania=%d seq=%dms conc=%dms speedup=%.2f rdzenie=%d",
        taskCount, seq, conc, (double)seq/conc, Runtime.getRuntime().availableProcessors());
}
